import contextlib,io,json,os,subprocess,sys,time
from pathlib import Path
from types import SimpleNamespace as NS
from unittest.mock import patch
from training.holistic_migration import camera,webcam
from training.holistic_migration.features import RawFrame
meta=dict(protocol=1,width=2,height=1,frame_bytes=8,pixel_format='BGRA',device_type=camera.BUILTIN_TYPE,continuity=False,device_sha256='a'*64)
child_code="import os,sys,json,struct\nos.write(1,json.dumps(json.loads(sys.argv[1])).encode()+b'\\n')\nif sys.argv[2]=='during_processing':\n os.write(1,struct.pack('>dI',0.,8)+bytes(8))\n os.read(int(sys.argv[3]),1)\nos.write(2,b'private native sentinel\\n')\nsys.exit(7)\n"
rows=[]
for mode in ('next_frame','during_processing'):
 calls=[];captures=[];children=[];primaries=[]
 gate_read,gate_write=os.pipe()
 faults={stage:OSError('private '+stage+' sentinel') for stage in ('diagnostic.stderr','report.write','report.close')}
 for e in faults.values():e.__cause__=RuntimeError('private secondary cause sentinel')
 causes={stage:e.__cause__ for stage,e in faults.items()}
 class Report:
  payload='';closed=False
  def write(self,text):
   calls.append('report.write');self.payload=text;raise faults['report.write']
  def flush(self):calls.append('report.flush')
  def close(self):calls.append('report.close');raise faults['report.close']
 class Stderr(io.StringIO):
  def write(self,text):calls.append('diagnostic.stderr');raise faults['diagnostic.stderr']
 stream=Report()
 binding=NS(binary=Path(sys.executable),source_sha256='b'*64,binary_sha256='c'*64,receipt=Path('/synthetic/binding.json'))
 def spawn(command,**kwargs):
  p=subprocess.Popen([sys.executable,'-E','-B','-c',child_code,json.dumps(meta),mode,str(gate_read)],pass_fds=(gate_read,),**kwargs)
  children.append(p);return p
 def make_capture(binding,**kwargs):
  with patch.object(camera,'verify_binding'):
   cap=camera.OwnedCapture(binding,popen=spawn,**kwargs)
  captures.append(cap)
  original_next=cap.next_frame;original_reconcile=cap.raise_if_failed
  def next_frame(deadline):
   try:return original_next(deadline)
   except camera.CaptureError as e:primaries.append(('next_frame',e));raise
  def reconcile():
   try:return original_reconcile()
   except camera.CaptureError as e:primaries.append(('reconcile',e));raise
  cap.next_frame=next_frame;cap.raise_if_failed=reconcile
  until=time.monotonic()+2
  with cap.condition:
   while ((cap.pending is None if mode=='during_processing' else cap.error is None) and time.monotonic()<until):cap.condition.wait(.01)
  assert (cap.pending is not None and cap.error is None) if mode=='during_processing' else isinstance(cap.error,EOFError)
  return cap
 class Detector:
  def detect(self,rgb,timestamp):
   calls.append('detector.detect');cap=captures[0]
   os.write(gate_write,b'x');assert cap.process.wait(timeout=2)==7
   until=time.monotonic()+2
   with cap.condition:
    while cap.error is None and time.monotonic()<until:cap.condition.wait(.01)
   assert isinstance(cap.error,EOFError)
   return RawFrame(timestamp,None,None,None)
  def close(self):calls.append('detector.close')
 class CV:
  WINDOW_AUTOSIZE=1;WND_PROP_VISIBLE=1
  def namedWindow(self,*a):calls.append('window.create')
  def imshow(self,*a):pass
  def waitKey(self,*a):return ord('q')
  def getWindowProperty(self,*a):return 1
  def destroyWindow(self,*a):calls.append('window.close')
 runtime=NS(build=lambda p:binding,capture=make_capture,detector=lambda p:Detector(),pack=lambda f:[0.]*153,cv=CV(),clock=time.monotonic,detector_version='synthetic',gui_version='synthetic')
 options=webcam.Options(Path('/synthetic/model.task'),Path('/synthetic/build'),5.,Path('/synthetic/report.json'))
 opened=Path.open
 def open_report(path,*a,**kw):return stream if path==options.report else opened(path,*a,**kw)
 error=None;result=None
 try:
  with patch.object(webcam,'validate_options'),patch.object(camera,'digest',return_value='d'*64),patch.object(Path,'open',open_report),patch.object(webcam,'prepare_rgb',return_value=None),patch.object(webcam,'render',return_value=None),contextlib.redirect_stderr(Stderr()):
   try:result=webcam.run_preview(options,runtime=runtime)
   except BaseException as e:error=e
  assert captures, repr(error)
  cap=captures[0];first=primaries[0][1]
  assert error is first and error.__cause__ is cap.error and isinstance(cap.error,EOFError)
  assert error.finalization_errors==tuple((stage,faults[stage]) for stage in ('diagnostic.stderr','report.write','report.close'))
  assert all(e.__cause__ is causes[stage] for stage,e in error.finalization_errors)
  assert 'sentinel' not in '\n'.join(error.__notes__) and 'sentinel' not in stream.payload
  assert calls.count('report.close')==1 and 'report.flush' not in calls and result is None
  assert cap.process.poll()==7 and cap.process.stdout.closed and cap.process.stderr.closed
  assert not cap.reader_thread.is_alive() and not cap.stderr_thread.is_alive()
  assert 'detector.close' in calls and 'window.close' in calls
  summary=json.loads(stream.payload);assert summary['terminal']=='error' and summary['source_failure'] and summary['live_acceptance'] is False
  assert summary['counts']['processed']==int(mode=='during_processing')
  rows.append(dict(mode=mode,raised_type=type(error).__name__,same_first_production_primary=error is first,cause_is_original_reader_error=error.__cause__ is cap.error,secondary_stages=[stage for stage,e in error.finalization_errors],secondary_causes_preserved=True,safe_notes=True,report_private_text_absent=True,report_close_attempts=calls.count('report.close'),report_close_succeeded=stream.closed,processed=summary['counts']['processed'],terminal=summary['terminal'],native_exit=cap.process.returncode,child_reaped=True,pipes_closed=True,threads_stopped=True,detector_and_window_closed=True,returned_normally=False))
 finally:
  os.close(gate_read);os.close(gate_write)
  for p in children:
   if p.poll() is None:p.kill();p.wait(timeout=2)
   for pipe in (p.stdout,p.stderr):
    if not pipe.closed:pipe.close()
print(json.dumps(rows,sort_keys=True))

